import{_ as t,o as n,c as a,ai as s}from"./chunks/framework.Ci0kozOl.js";const g=JSON.parse('{"title":"Agentic Development","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/agentic/index.md","filePath":"3.0/agentic/index.md","lastUpdated":1785947307000}'),o={name:"3.0/agentic/index.md"};function i(l,e,r,c,p,d){return n(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="agentic-development" tabindex="-1">Agentic Development <a class="header-anchor" href="#agentic-development" aria-label="Permalink to &quot;Agentic Development&quot;">​</a></h1><p>UnoPim is built to be worked on <em>with</em> AI — not just to ship an in-app assistant. The <strong>Agentic Development</strong> toolkit gives both end users and developers a set of AI-native interfaces into a UnoPim instance, each tuned for a different audience and workflow.</p><p>There are three pillars:</p><table tabindex="0"><thead><tr><th>Pillar</th><th>Audience</th><th>What it does</th></tr></thead><tbody><tr><td><strong>AI Agent</strong></td><td>Catalog managers, business users</td><td>A conversational chat widget inside the admin panel with 38+ PIM tools — search, create, bulk edit, enrich, translate, plan multi-step workflows.</td></tr><tr><td><strong>Agentic Skills</strong></td><td>Developers using coding agents</td><td>Domain-specific skill packs (<code>SKILL.md</code>) that teach Claude Code, Cursor, Windsurf, and Copilot how UnoPim&#39;s architecture and conventions work, so generated code is correct on the first try.</td></tr><tr><td><strong>MCP Server</strong></td><td>Developers &amp; remote AI assistants</td><td>A <a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">Model Context Protocol</a> bridge that exposes the catalog, settings, and developer tools to any MCP-compatible client over HTTP (SSE) or stdio.</td></tr></tbody></table><hr><h2 id="how-they-fit-together" tabindex="-1">How They Fit Together <a class="header-anchor" href="#how-they-fit-together" aria-label="Permalink to &quot;How They Fit Together&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                     UnoPim Instance                       │</span></span>
<span class="line"><span>│                                                           │</span></span>
<span class="line"><span>│   ┌─────────────┐   ┌──────────────┐   ┌──────────────┐ │</span></span>
<span class="line"><span>│   │  AI Agent    │   │  MCP Server   │   │   Catalog &amp;   │ │</span></span>
<span class="line"><span>│   │ (chat widget)│──▶│ (HTTP + stdio)│──▶│   Settings    │ │</span></span>
<span class="line"><span>│   └─────────────┘   └──────┬───────┘   └──────────────┘ │</span></span>
<span class="line"><span>│                            │                              │</span></span>
<span class="line"><span>└────────────────────────────┼──────────────────────────────┘</span></span>
<span class="line"><span>                             │ MCP protocol</span></span>
<span class="line"><span>              ┌──────────────┼──────────────┐</span></span>
<span class="line"><span>              ▼              ▼              ▼</span></span>
<span class="line"><span>        Claude Code      Cursor         Copilot</span></span>
<span class="line"><span>              ▲</span></span>
<span class="line"><span>              │ Agentic Skills (SKILL.md)</span></span>
<span class="line"><span>              │ — domain context for the coding agent</span></span>
<span class="line"><span>              └──────────────────────────────</span></span></code></pre></div><ul><li>The <strong>AI Agent</strong> lives inside the app and talks to your catalog directly. It is the right entry point for non-technical users who want to manage products in natural language.</li><li>The <strong>MCP Server</strong> exposes that same catalog (plus developer tooling) to <em>external</em> AI editors, so a developer in Cursor or Claude Code can read, write, and scaffold without leaving the IDE.</li><li><strong>Agentic Skills</strong> ride alongside the coding agent. They do not call UnoPim themselves — they inject UnoPim&#39;s conventions (Concord packages, <code>wk_</code> table prefix, repository pattern, cURL connectors, translation rules) into the agent&#39;s context so the code it writes — or the code it writes <em>through</em> the MCP Server — follows UnoPim standards.</li></ul><hr><h2 id="what-makes-unopim-ai-friendly" tabindex="-1">What Makes UnoPim AI-Friendly <a class="header-anchor" href="#what-makes-unopim-ai-friendly" aria-label="Permalink to &quot;What Makes UnoPim AI-Friendly&quot;">​</a></h2><p>UnoPim is designed so AI assistants are first-class citizens, not bolted-on afterthoughts:</p><ul><li><strong>Native tool calling</strong> — the AI Agent ships 38+ PIM tools built on <a href="https://github.com/prism-php/prism" target="_blank" rel="noreferrer">prism-php/prism</a>, so the LLM acts on your catalog directly instead of guessing.</li><li><strong>A standard protocol</strong> — the MCP Server speaks the open <a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">Model Context Protocol</a>, so any compatible editor connects without custom glue.</li><li><strong>Codified conventions</strong> — the Agentic Skills encode UnoPim&#39;s Concord architecture and coding standards, so generated code follows the rules (repository pattern, <code>wk_</code> table prefix, cURL connectors, translation requirements) the first time.</li><li><strong>Security by default</strong> — ACL enforcement, rate limiting, audit logging, command whitelisting, and approval queues apply to every AI-driven action.</li></ul><h2 id="what-you-can-build" tabindex="-1">What You Can Build <a class="header-anchor" href="#what-you-can-build" aria-label="Permalink to &quot;What You Can Build&quot;">​</a></h2><p>A few examples of what these tools unlock:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;Find all products in the Electronics category missing a description,</span></span>
<span class="line"><span> generate one for each, and translate it to every active locale.&quot;</span></span>
<span class="line"><span>            → AI Agent (search + bulk edit + auto-translation)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;Scaffold a WooCommerce connector plugin with credential storage,</span></span>
<span class="line"><span> a connection test, and an export profile.&quot;</span></span>
<span class="line"><span>            → Agentic Skills (unopim-plugin-development)</span></span>
<span class="line"><span>            + MCP Server (generate_plugin, run_command)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;What&#39;s the schema for products? Then create 20 demo products</span></span>
<span class="line"><span> with realistic attributes and verify they imported correctly.&quot;</span></span>
<span class="line"><span>            → MCP Server (get_catalog_schema + upsert_products + search_products)</span></span></code></pre></div><hr><h2 id="choosing-the-right-tool" tabindex="-1">Choosing the Right Tool <a class="header-anchor" href="#choosing-the-right-tool" aria-label="Permalink to &quot;Choosing the Right Tool&quot;">​</a></h2><ul><li><strong>&quot;I want to manage my catalog by chatting.&quot;</strong> → Use the <a href="./ai-agent.html">AI Agent</a>.</li><li><strong>&quot;I&#39;m coding an UnoPim plugin and want my AI assistant to write correct UnoPim code.&quot;</strong> → Install the <a href="./agent-skills.html">Agentic Skills</a>.</li><li><strong>&quot;I want my AI editor to read/write my live catalog and run Artisan commands.&quot;</strong> → Set up the <a href="./mcp-server.html">MCP Server</a>.</li></ul><p>These are complementary. A typical developer setup installs the Agentic Skills <strong>and</strong> connects the MCP Server: the skills tell the agent <em>how</em> to write UnoPim code, and the MCP Server gives it the <em>hands</em> to inspect the live instance, scaffold plugins, and verify changes.</p><hr><h2 id="in-this-section" tabindex="-1">In This Section <a class="header-anchor" href="#in-this-section" aria-label="Permalink to &quot;In This Section&quot;">​</a></h2><ul><li><strong><a href="./ai-agent.html">AI Agent Integration</a></strong> — The in-app conversational assistant: chat widget, tool system, approval queues, auto-enrichment, semantic search.</li><li><strong><a href="./magic-ai-platform.html">MagicAI Platform Management</a></strong> — Multi-provider AI configuration powering the agent and content generation.</li><li><strong><a href="./agent-skills.html">Agentic Skills</a></strong> — The six UnoPim skill packs, how to install them, and how to author your own.</li><li><strong><a href="./mcp-server.html">MCP Server</a></strong> — Installing the MCP bridge, connecting AI editors, available tools, configuration, and security.</li><li><strong><a href="./building-integrations.html">Building an Integration with AI</a></strong> — End-to-end walkthrough: scaffold a connector with the skills + MCP, from credentials to export profile to review.</li><li><strong><a href="./building-agent-tools.html">Building Custom Agent Tools</a></strong> — Extend the AI Agent with your own <code>PimTool</code> classes: ACL, approval, registration, and testing.</li><li><strong><a href="./extending-mcp.html">Extending the MCP Bridge</a></strong> — Add custom MCP capabilities via dynamic Skills (low-code) or PHP Core Tools.</li><li><strong><a href="./recipes.html">Agentic Recipes</a></strong> — End-to-end playbooks for building, enriching, and maintaining your catalog with AI.</li></ul>`,24)])])}const u=t(o,[["render",i]]);export{g as __pageData,u as default};
